complete_supplemental_units.content:
def initialize(name, trainer_type)
  super
  @character_ID          = 0
  @outfit                = 0
  @badges                = [false] * 8
  @money                 = GameData::Metadata.get.start_money
  @coins                 = 0
  @battle_points         = 0
  @soot                  = 0
  @pokedex               = Pokedex.new
  @has_pokedex           = false
  @has_pokegear          = false
  @has_running_shoes     = false
  @has_box_link          = false
  @seen_storage_creator  = false
  @has_exp_all           = false
  @mystery_gift_unlocked = false
  @mystery_gifts         = []
end

def initialize(name, trainer_type)
  @trainer_type = GameData::TrainerType.get(trainer_type).id
  @name         = name
  @id           = rand(2**16) | (rand(2**16) << 16)
  @language     = pbGetLanguage
  @party        = []
end

class NPCTrainer < Trainer
  attr_accessor :version
  attr_accessor :items
  attr_accessor :lose_text
  attr_accessor :win_text

  def initialize(name, trainer_type, version = 0)
    super(name, trainer_type)
    @version   = version
    @items     = []
    @lose_text = nil
    @win_text  = nil
  end
end

def self.get(player_id = 1)
  validate player_id => Integer
  return self::DATA[player_id] if self::DATA.has_key?(player_id)
  return self::DATA[1]
end

def initialize
  @battle     = nil
  @abortable  = false
  @aborted    = false
  @battleEnd  = false
  @animations = []
end
